INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p179:source_text','full_text','en','CLUTCH
ADJUSTMENTS
1
THROW-OUT STOP CLEARANCE
Service repair no - 33.25.03
Check and Adjust
1. Remove ECM. See ENGINE MANAGEMENT
SYSTEM - MEMS, Repairs.
2. Release engine compartment fuse box from
ECM mounting bracket.
3. Release clip securing main harness to ECM
mounting bracket.
4. Remove bolt securing ECM mounting bracket
to body.
5. Release ECM mounting bracket from body and
remove.
6. Depress clutch pedal to load clutch lever and
remove any free play.','source','source_extraction','en','Exact source text extraction; original layout remains available in page visual candidate.') ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
