INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p181:source_text','full_text','en','CLUTCH
REPAIRS
1
FLYWHEEL HOUSING COVER
Service repair no - 33.10.04.99
Remove
1. Remove starter motor. See ELECTRICAL,
Repairs.
2. Remove bonnet. See BODY, Exterior
fittings.
3. Remove ECM. See ENGINE MANAGEMENT
SYSTEM - MEMS, Repairs.
4. Remove engine breather/oil separator. See
EMISSION CONTROL, Repairs.
5. Remove cover from engine compartment fuse
box.
6. Remove fusible link.
7. Release retaining tag and disconnect engine
harness lead from fuse box.
8. Release engine compartment fuse box from
ECM mounting bracket.
9. Release clip securing main harness to ECM
mounting bracket.
10. Remove bolt securing ECM mounting bracket
to body.
11. Release ECM mounting bracket from body and
remove.
12. Remove bolt securing earth leads to body.','source','source_extraction','en','Exact source text extraction; original layout remains available in page visual candidate.') ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
