INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p187:source_text','full_text','en','CLUTCH
REPAIRS
7
REVISED: 12/96
15. Remove 6 bolts securing pressure plate to
flywheel.
16. Remove pressure plate assembly.
17. Remove drive plate from flywheel.
Refit
1. Clean flywheel and pressure plate. Check
diaphragm spring for wear and fractures.
Renew flywheel and pressure plate as an
assembly if either component shows signs of
wear or damage.
2. Clean crankshaft and pressure plate hub.
3. Clean inside of flywheel housing.
4. Position drive plate on flywheel.
5. Fit pressure plate and align to flywheel, fit bolts
but DO NOT tighten.
6. Fit clutch aligning tool 18G 684.
7. Tighten pressure plate to flywheel bolts to 25
Nm.
8. Remove clutch aligning tool.
9. Check crankshaft primary gear end-float. See
ENGINE, Adjustments.
10. Grease splines of crankshaft primary gear.
11. Fit flywheel and clutch assembly to crankshaft.
12. Fit keyplate and NEW flywheel retaining bolt.
13. Tighten flywheel retaining bolt to 150 Nm.
14. Stake lock washer into slots on clutch hub.
15. Remove bolts securing flywheel locking tool to
flywheel housing.
16. Remove flywheel locking tool.
17. Clean thrust bearing sleeve.
18. Fit thrust bearing sleeve to clutch hub.
19. Fit clutch release bearing. See this section.
20. Fit CKP sensor. See ENGINE
MANAGEMENT SYSTEM - MEMS, Repairs.','source','source_extraction','en','Exact source text extraction; original layout remains available in page visual candidate.') ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
