INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p188:source_text','full_text','en','CLUTCH
8
REPAIRS
REVISED: 12/96
RELEASE BEARING
Service repair no - 33.25.12
Remove
1. Remove flywheel housing cover. See this
section.
2. Remove ’O’ ring retaining bearing to plunger.
3. Remove bearing assembly from plunger.
4. Remove retainer securing locating plate to
bearing.
5. Remove locating plate from bearing.
Refit
1. Clean mating face of locating plate and release
bearing.
2. Examine release bearing for signs of wear or
damage, renew if necessary.
CAUTION: Bearing is packed with grease,
DO NOT eash in solvent.
3. Apply grease to plunger shaft.
4. Position locating plate to bearing.
5. Fit location plate retainer.
6. Fit bearing assembly onto plunger.
7. Fit new ’O’ ring securing bearing to plunger.
8. Fit flywheel housing cover. See this section.
MASTER CYLINDER
Service repair no - 33.20.01
Remove
1. Remove ECM. See ENGINE MANAGEMENT
SYSTEM - MEMS, Repairs.
2. Remove air cleaner. See ENGINE
MANAGEMENT SYSTEM - MEMS, Repairs.
3. Release engine management relay module
from mounting bracket and position aside.
4. Release brake servo vacuum pipe from clip,
move vacuum pipe and engine harness aside.','source','source_extraction','en','Exact source text extraction; original layout remains available in page visual candidate.') ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
