INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p189:source_text','full_text','en','CLUTCH
REPAIRS
9
ISSUED: 12/96
5. Attach bleed tube to bleed screw on slave
cylinder. Remove cylinder cap and open bleed
screw, pump clutch pedal to drain fluid from
cylinder.
6. Loosen unions securing pipe to master and
slave cylinders.
7. Remove clutch pipe.
CAUTION: Plug the connections.
8. Release heater air intake duct from adapter
inside vehicle and remove duct.
9. Remove split pin from clutch pedal clevis pin.
10. Remove clutch pedal clevis pin.
11. Remove 2 nuts securing master cylinder to
body.
12. Remove master cylinder and discard gasket.','source','source_extraction','en','Exact source text extraction; original layout remains available in page visual candidate.') ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
