INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p190:source_text','full_text','en','CLUTCH
10
REPAIRS
ISSUED: 12/96
Refit
1. Clean mating face of master cylinder and body.
2. Fit master cylinder with new gasket to body.
3. Align push rod to clutch pedal.
4. Fit and tighten nuts securing master cylinder to
body.
5. Lubricate and fit clevis pin securing push rod to
pedal.
6. Secure clutch pedal clevis pin with a new split
pin.
7. Fit fresh air intake duct to heater and connect
to adapter on body.
8. Clean unions on clutch pipe, master cylinder
and slave cylinder. Fit clutch pipe and tighten
unions to 14 Nm.
9. Reposition engine harness and secure brake
servo vacuum pipe to clip.
10. Secure engine management relay module to
mounting bracket.
11. Bleed clutch. See Adjustments.
12. Fit air cleaner. See ENGINE MANAGEMENT
SYSTEM - MEMS, Repairs.
SLAVE CYLINDER
Service repair no - 33.35.01
Remove
1. Remove ECM. See ENGINE MANAGEMENT
SYSTEM - MEMS, Repairs.
2. Remove engine breather/oil separator. See
EMISSION CONTROL, Repairs.
3. Attach bleed tube to bleed screw on slave
cylinder. Remove master cylinder cap and
open bleed screw, pump clutch pedal to drain
fluid from cylinder.
4. Loosen unions securing pipe to master and
slave cylinder.
5. Remove clutch pipe.
CAUTION: Plug the connections.','source','source_extraction','en','Exact source text extraction; original layout remains available in page visual candidate.') ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
